import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第二册：实践与进步 · Lesson 57 Can I help you, madam?","description":"学习 情态动词的意义与形式，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 57 Can I help you, madam?","description":"学习 情态动词的意义与形式，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 情态动词的意义与形式，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 56 Faster than sound!","link":"/life/english/new-concept/book-2/unit-03/lesson-056"},"next":{"text":"第二册：实践与进步 · Lesson 58 A blessing in disguise?","link":"/life/english/new-concept/book-2/unit-03/lesson-058"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 56 Faster than sound!","link":"/life/english/new-concept/book-2/unit-03/lesson-056"},"next":{"text":"第二册：实践与进步 · Lesson 58 A blessing in disguise?","link":"/life/english/new-concept/book-2/unit-03/lesson-058"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-03/lesson-057.md","filePath":"life/english/new-concept/book-2/unit-03/lesson-057.md"}'),l={name:"life/english/new-concept/book-2/unit-03/lesson-057.md"};function i(s,e,r,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第二册-实践与进步-·-lesson-57-can-i-help-you-madam" tabindex="-1">第二册：实践与进步 · Lesson 57 Can I help you, madam? <a class="header-anchor" href="#第二册-实践与进步-·-lesson-57-can-i-help-you-madam" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 57 Can I help you, madam?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>顾客的衣着不能代表购买意愿，服务应根据明确需求展开；练习礼貌服务与宾语从句。本课的语言观察是：Can I help ...? 在服务场景中是主动提供帮助，不是要求顾客证明自己需要帮助。Would you like ...? 通常比直接命令更委婉。完成学习后，请写三句服务对话：提供帮助、确认尺寸、回应库存情况。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>serve</td><td>/sɜːv/</td><td>v.</td><td>服务</td><td>serve a customer</td></tr><tr><td>customer</td><td>/ˈkʌstəmə/</td><td>n.</td><td>顾客</td><td>a regular customer</td></tr><tr><td>respect</td><td>/rɪˈspekt/</td><td>n.</td><td>尊重</td><td>show respect</td></tr><tr><td>clothes</td><td>/kləʊðz/</td><td>n.</td><td>衣服（复数）</td><td>casual clothes</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>look down on — 轻视某人</li><li>treat somebody with respect — 尊重地对待某人</li></ul><h2 id="语法讲解-情态动词的意义与形式" tabindex="-1">语法讲解：情态动词的意义与形式 <a class="header-anchor" href="#语法讲解-情态动词的意义与形式" aria-label="Permalink to &quot;语法讲解：情态动词的意义与形式&quot;">​</a></h2><p>can、could、may、might、must 等情态动词后接动词原形，否定一般直接加 not，不需要 do。它们可能表示能力、许可、义务或推测，必须根据上下文区分；could 不总是过去时间，也能表示委婉请求或较弱的可能性。must not 表示禁止，do not have to 表示没有必要，二者意义完全不同。判断语气时先问说话人在提出要求还是评价证据。本课应用：Can I help ...? 在服务场景中是主动提供帮助，不是要求顾客证明自己需要帮助。Would you like ...? 通常比直接命令更委婉。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Would you like to see a different size?</p></blockquote><p>您想看看另一个尺寸吗？</p><p>Would you like 后接 to see，a different size 是宾语；would 在此不表过去时间。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>Would you like seeing 通常不是提出这次邀请的用法；用 Would you like to see。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请求句用自然上扬或礼貌降升调，重读 different size，而非每个词等重。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Would you like to see a different size? The customer asked for a smaller coat. The assistant checked the stock without commenting on her clothes.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句服务对话：提供帮助、确认尺寸、回应库存情况。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：Would you like 后接 to see，a different size 是宾语；would 在此不表过去时间。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：Would you like seeing 通常不是提出这次邀请的用法；用 Would you like to see。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 to/for：Would you like ___ try it on?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> would like 后接 to 不定式。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>顾客想要什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> A smaller coat.</p><p><strong>解析：</strong> 要求是尺寸更小，不是颜色更亮。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>用代词改写 try the coat on。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> try it on</p><p><strong>解析：</strong> 可分短语动词中代词放在动词和副词之间。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：情态动词的意义与形式。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-056">上一课</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-03/lesson-058">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const k=t(l,[["render",i]]);export{p as __pageData,k as default};
